-- Import des courriers arrivées 2006
-- Source : 2006.xlsx (feuille 2006).
-- La colonne CATEGORIES vaut partout « Demande SERVICES ».
-- txt_categorie est déduite de la désignation, comme pour 2009 à 2016.
--
--   N°                -> txt_numdordre (00001/jj-mm-aaaa) et txt_numcourier
--   DATE RECEPTION    -> dt_datearrivee et dt_datecourier
--   référence         -> « <N°> du jj-mm-aaaa »
--   PRENOMS + NOM     -> txt_prenomNom et txt_expediteur
--   DESIGNATIONS      -> txt_objet, puis txt_designation et txt_categorie
--   N° TF             -> txt_numTitreFoncier
--   N° LOT            -> txt_numLot
--   AGENTS TRAITEUR   -> txt_agenttraiteur
--   OBSERVATIONS      -> txt_observation
--
-- txt_typecourrier = BE si la désignation commence par « BE », sinon Individuel
-- txt_nombrepiece = 1
-- N° d'arrivée en doublon : suffixe -2
-- Dates illisibles reconstituées sur la ligne voisine : 0
-- Lignes importées : 1764
-- Lignes non importées :
--   ligne Excel 1053 : N° 1051 sans désignation ni nom
--
-- Répartition des catégories :
--    1724  Demande SERVICES
--      21  Information
--      18  Convocation - Invitation
--       1  Réclamation - Signalement
-- Désignations :
--    1076  Morcellements
--     241  Demande de Cession définitive
--     160  Demande de terrain/Echange
--      53  Demande de délimitation
--      44  Duplication de CIC
--      43  Demande de Régularisation par voie de Bail
--      22  Litiges
--      17  Demande d'états des lieux
--      15  Réquisition d'immatriculation
--      14  Visite de site
--      10  Autres
--       9  Demande d'évaluation
--       8  Autorisation de morceler
--       8  Réceptions de lotissements
--       7  Demande de Titre foncier
--       6  Autorisation de lotir
--       5  Tribunal
--       5  Note de service
--       4  Demande de situation foncière
--       3  Réunion
--       3  Demande d'extraits de plan
--       2  Décision - Arrêté
--       2  Autorisation de construction
--       2  Circulaire
--       1  PV - Compte - rendu
--       1  Demande d'attestation du Cadastre
--       1  Formation
--       1  Plainte
--       1  Document administratif

